def _download(store, user, note_id):
    note = store.get(note_id)
    if note is None:
        return _error(404, "no such note")
    headers = {"Content-Type": "text/plain; charset=utf-8",
               "Content-Disposition": f'attachment; filename="note-{note.id}.txt"'}
    return Response(200, f"{note.title}\n\n{note.body}\n", headers)
